<template>
<v-card rounded="xl" flat border><v-card-text><div class="ledger-heading"><div><v-chip color="primary" size="small">{{typeNames[record.media_type]||'检测记录'}} · 历史记录</v-chip><h2 class="mt-3">{{record.title}}</h2><p class="caption mt-2">建档于 {{dateText(record.created_at)}} · 只读查看</p></div><v-btn color="grey-darken-1" variant="outlined" @click="$emit('close')">返回列表</v-btn></div>
<div class="ledger-stats"><div><span>{{record.media_type==='STREAM'?'采样帧数':'识别次数'}}</span><strong>{{detections.length}}</strong></div><div><span>最近一帧垃圾数量</span><strong>{{latest?.result.num_detections??'—'}}</strong></div><div><span>预测次数</span><strong>{{traces.length}}</strong></div></div>
<v-alert :type="lastTrace?.status==='COMPLETED'?'info':'warning'" variant="tonal" class="mb-5">{{lastTrace?.result.conclusion||lastTrace?.result.reason||'这条记录尚未进行来源预测'}}</v-alert>
<h3 class="mb-3">观测信息</h3><div class="observation-info"><p><b>观测时间</b>{{dateText(lastTrace?.parameters?.captured_at||record.captured_at)}}</p><p><b>观测位置</b>{{areaText(lastTrace?.parameters?.observation_area||record.observation_area)}}</p><p v-if="record.metadata?.device_id"><b>设备编号</b>{{record.metadata.device_id}}</p></div>
<div class="my-4"><v-btn color="grey-darken-1" variant="outlined" size="small" @click="showInfo=!showInfo">{{showInfo?'收起其他信息':'其他信息'}}</v-btn><div v-if="showInfo" class="info-flat mt-3"><div v-for="(value,key) in record.metadata" :key="key" class="metadata-row"><b>{{key}}</b><span>{{typeof value==='object'?JSON.stringify(value):value}}</span></div><p v-if="!Object.keys(record.metadata||{}).length" class="caption">暂无信息</p></div></div>
<h3 class="mb-3">识别与预测记录</h3><v-table hover><thead><tr><th>采样 / 检测时间</th><th>垃圾数量</th><th>主要类别</th><th>预测进度</th><th></th></tr></thead><tbody><tr v-for="r in detections" :key="r.id" :class="{chosen:detail?.id===r.id}"><td>{{dateText(r.created_at)}}</td><td>{{r.result.num_detections}} 个</td><td>{{classCounts(r.result).slice(0,2).map(c=>c.name+' '+c.count+'个').join('、')||'无检出目标'}}</td><td>{{paired(r)?statusNames[paired(r).status]||paired(r).status:'尚未预测'}}</td><td><v-btn variant="text" color="primary" @click="detail=r">查看详情</v-btn></td></tr></tbody></v-table><p v-if="!detections.length" class="empty">暂无识别结果</p>
<div v-if="detail" class="sample-detail"><div class="sample-image"><img :src="'/api/media/frames/'+detail.image_path.split(/[\\/]/).pop()" alt="本次识别的原始画面"/><div class="actions mt-3"><v-chip v-for="c in classCounts(detail.result)" :key="c.name" color="primary">{{c.name}} {{c.count}} 个</v-chip></div></div><div><h3 class="mb-3">{{dateText(detail.created_at)}} 的分析结果</h3><template v-if="paired(detail)"><v-alert variant="tonal" type="info">{{paired(detail).result.conclusion||paired(detail).result.reason}}</v-alert><p class="caption my-3">{{paired(detail).result.flow?.provider||'暂无可用流场'}} · {{statusNames[paired(detail).status]||paired(detail).status}}</p><v-table v-if="paired(detail).result.candidate_sources?.length"><thead><tr><th>候选地点</th><th>经过粒子</th><th>最近距离</th></tr></thead><tbody><tr v-for="s in paired(detail).result.candidate_sources.slice(0,5)" :key="s.id"><td>{{s.name}}</td><td>{{s.encounter_particles}}</td><td>{{s.closest_distance_km==null?'—':s.closest_distance_km+' km'}}</td></tr></tbody></v-table><p class="caption mt-3">可能来源尚未确认，接近轨迹不等于排放证据。</p></template><p v-else>本次仅完成识别，暂无关联预测。</p></div></div>
<v-expansion-panels v-if="unpaired.length" class="mt-4"><v-expansion-panel title="其他预测记录"><v-expansion-panel-text><v-list><v-list-item v-for="r in unpaired" :key="r.id" :title="r.result.conclusion||r.result.reason" :subtitle="dateText(r.created_at)+' · '+(statusNames[r.status]||r.status)"/></v-list></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
<div class="actions-right mt-5"><v-btn color="grey-darken-1" variant="outlined" @click="$emit('close')">返回记录列表</v-btn><v-btn color="primary" :loading="predicting" :disabled="!detections.length" @click="$emit('repredict',detail||latest)">重新预测{{detail?'当前一帧':'最近一帧'}}</v-btn><v-btn v-if="['IMAGE','VIDEO'].includes(record.media_type)" color="primary" @click="$emit('copy',record)">用此素材新建检测</v-btn></div>
</v-card-text></v-card>
</template>
<script setup>
import {ref,computed} from 'vue'
import {typeNames,statusNames,dateText,areaText,classCounts} from '../utils/display'
const props=defineProps({record:Object,detections:Array,traces:Array,predicting:Boolean});defineEmits(['close','copy','repredict']);const showInfo=ref(false),detail=ref(null)
const latest=computed(()=>props.detections[0]),lastTrace=computed(()=>props.traces[0])
function paired(d){return props.traces.find(t=>(t.parameters?.detection_id||t.result?.detection_id)===d.id)}
const unpaired=computed(()=>props.traces.filter(t=>!props.detections.some(d=>(t.parameters?.detection_id||t.result?.detection_id)===d.id)))
</script>
<style scoped>.info-flat{padding:12px 0;border-top:1px solid #e5e7eb}.ledger-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}.ledger-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.ledger-stats>div{padding:20px;background:#f5f8fd;border-radius:14px}.ledger-stats span{display:block;color:#6b7280;font-size:13px}.ledger-stats strong{font-size:28px;display:block;margin-top:8px;font-variant-numeric:tabular-nums}.observation-info{padding:16px 20px;background:#f8fafc;border-radius:12px;line-height:2}.observation-info b{display:inline-block;width:95px;color:#64748b;font-weight:500}.metadata-row{display:flex;gap:20px;line-height:2;overflow-wrap:anywhere}.sample-detail{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:24px;margin-top:24px;padding:20px;border:1px solid #e5e7eb;border-radius:16px}.sample-image img{max-width:100%;max-height:380px;display:block;margin:auto}.chosen{background:#f0f6ff}@media(max-width:850px){.sample-detail{grid-template-columns:1fr}.ledger-stats{gap:8px}.ledger-stats>div{padding:12px}}</style>
